rule.definition:
/* The purpose of this function is to return a list of asks containing only the highest versions of those asks.
  For example, if ask A has versions 1 and 2, and ask B has versions 1,2, and 3, The returning list will be 
  {version 2 of ask A, and version 3 of ask B}*/
a!localVariables(
  local!latestVerions: #"SYSTEM_SYSRULES_forEach"(
    /* Runs over each ask to find the highest version for each askID */
    items: ri!asks,
    expression: index(
      index(
        ri!asks,
        wherecontains(fv!item.askID, ri!asks.askId)
      ),
      wherecontains(
        tointeger(
          max(
            /* This index returns a list of all of the versions for one askID
              The max of these versions will then be found*/
            index(
              ri!asks,
              wherecontains(fv!item.askID, ri!asks.askId)
            ).version
          )
        ),
        /*Now the index of the ask with the highest version number will be returned*/
        index(
          ri!asks,
          wherecontains(fv!item.askID, ri!asks.askId)
        ).version
      )
      /*So now the ask with the highest version for this askId is pulled from ri!asks
        using the index we found in the inner index*/
    )
  ),
  /* Because this function runs over every element in the list and generates the highest verion for each element,
      we have to union in order to remove the duplicates. */
  a!flatten(
    union(
      local!latestVerions,
      local!latestVerions
    )
  )
)
